import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import fs from 'fs';
import path from 'path';
import { createScene } from './data/object.js';

async function exportSceneToOBJ() {
  try {
    // Create the scene
    const scene = createScene();

    // Apply -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
    // This is done by creating a wrapper group with the rotation applied
    const rotationWrapper = new THREE.Group();
    rotationWrapper.rotation.x = -Math.PI / 2;
    rotationWrapper.add(scene);

    // Export to OBJ format
    const exporter = new OBJExporter();
    const objData = exporter.parse(rotationWrapper);

    // Ensure output directory exists
    const outputDir = '/root/output';
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    // Write to file
    const outputPath = path.join(outputDir, 'object.obj');
    fs.writeFileSync(outputPath, objData);

    console.log(`✓ Successfully exported to ${outputPath}`);
    console.log(`File size: ${fs.statSync(outputPath).size} bytes`);

  } catch (error) {
    console.error('Error during export:', error);
    process.exit(1);
  }
}

exportSceneToOBJ();

